#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "reference_owned_dmx_projection.h"
#include "owned_dmx_class_resolve_registry.h"
#include "global_flex_binding_lifecycle.h"
#include <iostream>
#include <unordered_set>
#include <optional>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=2)throw std::runtime_error("session required");auto graph=loadGraph(argv[1]);using Projection=RecoveredOwnedDmxReferenceProjectionCandidate<Graph>;Projection projection(graph,[](const std::string&,auto&)->uint32_t{throw std::runtime_error("external adapter required");});OwnedDmxClassResolveRegistryCandidate<Projection>registry;std::unordered_set<uint32_t>called;std::unordered_map<uint32_t,RecoveredFlexBindingCache>caches;size_t expected=0;registry.bind("DmeGlobalFlexControllerOperator",[&](Projection&p,uint32_t id){if(&p!=&projection||!called.insert(id).second)throw std::runtime_error("class dispatch identity");for(auto&flags:p.typedAttributeFlags.at(id))if(!(flags&0x80))throw std::runtime_error("premature typed cleanup");auto&cache=caches[id];recoveredLazyFlexBindingCandidate(cache,[&]{return id;},[&]()->std::optional<uint32_t>{return p.elementHandles.at(id);});});for(uint32_t id=0;id<graph.elements.size();++id){for(auto&flags:projection.typedAttributeFlags.at(id))flags|=0x80;projection.scene.queues.registration.append(projection.elementHandles[id]);if(graph.strings.at(graph.elements[id].type)=="DmeGlobalFlexControllerOperator")++expected;}projection.scene.queues.registration.append(0xffffffff);auto result=registry.dispatch(projection);if(result.registered!=expected||result.unregistered!=graph.elements.size()-expected||called.size()!=expected)throw std::runtime_error("dispatch counts");for(auto&item:caches)if(item.second.index!=item.first||item.second.destination!=projection.elementHandles.at(item.first))throw std::runtime_error("callback binding");if(!projection.scene.queues.registration.handles.empty())throw std::runtime_error("queue remains");for(uint32_t id=0;id<graph.elements.size();++id)for(size_t j=0;j<graph.elements[id].attributes.size();++j)if(projection.typedAttributeFlags.at(id).at(j)!=graph.elements[id].attributes[j].type)throw std::runtime_error("typed flags not cleaned");auto second=registry.dispatch(projection);if(second.registered||second.unregistered)throw std::runtime_error("repeat dispatch");validateGraph(projection.graph);std::cout<<"owned class callback routing="<<expected<<" unregistered="<<result.unregistered<<" missing handle skipped, repeated drain empty passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
